const config = $('Workflow Config').first().json;

const maxPages = Number(config.maxPages);
if (!Number.isInteger(maxPages) || maxPages < 1) {
  throw new Error(`Invalid maxPages in Workflow Config: ${config.maxPages}`);
}

return [
  {
    json: {
      page: 1,
      maxPages,
      pagesFetched: 0,
      runId: String($execution.id),
      runStartedAt: $now.toISO(),
      products: [],
    },
  },
];

const BASE_ORIGIN = 'https://webscraper.io';

const state = $('Pagination State').first().json;
const response = $input.first().json;
const html = String(response.data ?? response.body ?? '');
const page = Number(state.page);

const decodeEntities = (value) =>
  String(value)
    .replace(/&quot;/g, '"')
    .replace(/&#0?39;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/\s+/g, ' ')
    .trim();

const sanitizePrice = (raw) => {
  const cleaned = String(raw ?? '')
    .replace(/[^0-9.,-]/g, '')
    .replace(/,/g, '');
  const value = parseFloat(cleaned);
  return Number.isFinite(value) ? Math.round(value * 100) / 100 : null;
};

const toAbsoluteUrl = (href) => {
  if (/^https?:\/\//i.test(href)) return href;
  return `${BASE_ORIGIN}${href.startsWith('/') ? '' : '/'}${href}`;
};

const readAttribute = (tag, attribute) => {
  const match = tag.match(new RegExp(`\\b${attribute}="([^"]*)"`, 'i'));
  return match ? decodeEntities(match[1]) : null;
};

const blocks = html.split(/class="[^"]*\bthumbnail\b[^"]*"/i).slice(1);

const pageProducts = [];
const invalidRows = [];

for (const block of blocks) {
  const anchorTag = (block.match(/<a\b[^>]*\bclass="[^"]*\btitle\b[^"]*"[^>]*>/i) || [])[0];
  const anchorText = (block.match(/<a\b[^>]*\bclass="[^"]*\btitle\b[^"]*"[^>]*>([\s\S]*?)<\/a>/i) || [])[1];
  const href = anchorTag ? readAttribute(anchorTag, 'href') : null;
  const title = (anchorTag && readAttribute(anchorTag, 'title')) || (anchorText ? decodeEntities(anchorText) : null);

  const rawPrice =
    (block.match(/itemprop="price"[^>]*>([^<]+)</i) || [])[1] ??
    (block.match(/class="[^"]*\bprice\b[^"]*"[^>]*>\s*(?:<[^>]+>\s*)*([^<]+)/i) || [])[1];
  const price = sanitizePrice(rawPrice);

  const rawReviews =
    (block.match(/itemprop="reviewCount"[^>]*>\s*(\d+)/i) || [])[1] ??
    (block.match(/(\d+)\s+reviews?/i) || [])[1];
  const reviewCount = rawReviews !== undefined ? parseInt(rawReviews, 10) : 0;

  const rating = parseInt((block.match(/data-rating="(\d+)"/i) || [])[1] ?? '0', 10);
  const descriptionRaw = (block.match(/class="[^"]*\bdescription\b[^"]*"[^>]*>([\s\S]*?)<\/p>/i) || [])[1];

  if (!href || !title || price === null) {
    invalidRows.push({ href, title, rawPrice: rawPrice ?? null });
    continue;
  }

  const url = toAbsoluteUrl(href);
  const productId = (url.match(/\/product\/(\d+)/) || [])[1] ?? url;

  pageProducts.push({
    product_id: String(productId),
    title,
    description: descriptionRaw ? decodeEntities(descriptionRaw) : '',
    price,
    currency: 'USD',
    review_count: reviewCount,
    rating,
    url,
    page,
  });
}

const hasNextPage = /rel="next"/i.test(html);
const pageNumbers = [...html.matchAll(/[?&]page=(\d+)/g)].map((m) => parseInt(m[1], 10));
const totalPagesDetected = pageNumbers.length ? Math.max(page, ...pageNumbers) : page;

const merged = new Map((state.products || []).map((p) => [p.product_id, p]));
for (const product of pageProducts) {
  if (!merged.has(product.product_id)) merged.set(product.product_id, product);
}

let status = 'ok';
let reason = null;
if (pageProducts.length === 0) {
  status = 'error';
  reason = `ZERO_PRODUCTS: page ${page} returned no parsable laptops (HTTP ${response.statusCode ?? 'n/a'}, ${html.length} bytes)`;
} else if (invalidRows.length > 0) {
  status = 'error';
  reason = `PARSE_FAILURE: ${invalidRows.length} product card(s) on page ${page} missing title/link/price`;
}

return [
  {
    json: {
      status,
      reason,
      page,
      maxPages: state.maxPages,
      pagesFetched: Number(state.pagesFetched || 0) + 1,
      hasNextPage,
      totalPagesDetected,
      pageProductCount: pageProducts.length,
      invalidRows,
      statusCode: response.statusCode ?? null,
      runId: state.runId,
      runStartedAt: state.runStartedAt,
      products: [...merged.values()],
    },
  },
];

const current = $input.first().json;

return [
  {
    json: {
      page: current.page + 1,
      maxPages: current.maxPages,
      pagesFetched: current.pagesFetched,
      runId: current.runId,
      runStartedAt: current.runStartedAt,
      products: current.products,
    },
  },
];

const result = $input.first().json;
const scrapedAt = $now.toISO();

const products = (result.products || []).map((product) => ({
  ...product,
  run_id: result.runId,
  scraped_at: scrapedAt,
}));

if (products.length === 0) {
  throw new Error(`Run ${result.runId} finished pagination with zero products; refusing to persist an empty snapshot.`);
}

return [
  {
    json: {
      runId: result.runId,
      runStartedAt: result.runStartedAt,
      scrapedAt,
      pagesFetched: result.pagesFetched,
      truncatedAtMaxPages: Boolean(result.hasNextPage) && result.page >= result.maxPages,
      productCount: products.length,
      products,
    },
  },
];

const snapshot = $('Finalize Snapshot').first().json;
const config = $('Workflow Config').first().json;
const anomalyThresholdPct = Number(config.priceAnomalyThresholdPct ?? 20);

const round2 = (value) => Math.round(value * 100) / 100;

const toNumber = (value) => {
  if (typeof value === 'number') return Number.isFinite(value) ? value : null;
  const parsed = parseFloat(String(value ?? '').replace(/[^0-9.-]/g, ''));
  return Number.isFinite(parsed) ? parsed : null;
};

const latestById = new Map();
for (const item of $input.all()) {
  const row = item.json || {};
  const productId = String(row.product_id ?? '').trim();
  const price = toNumber(row.price);
  if (!productId || price === null) continue;

  const timestamp = Date.parse(row.scraped_at) || 0;
  const previous = latestById.get(productId);
  if (!previous || timestamp >= previous.timestamp) {
    latestById.set(productId, { price, timestamp });
  }
}

const isBaselineRun = latestById.size === 0;

return snapshot.products.map((product) => {
  const previous = latestById.get(String(product.product_id));

  let changeType = 'UNCHANGED';
  let previousPrice = null;
  let priceDelta = 0;
  let priceDeltaPct = 0;

  if (!previous) {
    changeType = 'NEW';
  } else {
    previousPrice = previous.price;
    priceDelta = round2(product.price - previous.price);
    if (Math.abs(priceDelta) >= 0.01) {
      changeType = priceDelta > 0 ? 'PRICE_UP' : 'PRICE_DOWN';
      priceDeltaPct = previous.price > 0 ? round2((priceDelta / previous.price) * 100) : 0;
    } else {
      priceDelta = 0;
    }
  }

  const isAnomaly = changeType.startsWith('PRICE_') && Math.abs(priceDeltaPct) >= anomalyThresholdPct;

  return {
    json: {
      run_id: product.run_id,
      scraped_at: product.scraped_at,
      product_id: product.product_id,
      title: product.title,
      price: product.price,
      currency: product.currency,
      review_count: product.review_count,
      rating: product.rating,
      url: product.url,
      page: product.page,
      change_type: changeType,
      previous_price: previousPrice,
      price_delta: priceDelta,
      price_delta_pct: priceDeltaPct,
      is_anomaly: isAnomaly,
      is_baseline_run: isBaselineRun,
    },
  };
});

const MAX_LINES_PER_SECTION = 25;
const snapshot = $('Finalize Snapshot').first().json;
const changes = $input.all().map((item) => item.json);

const escapeMarkdown = (value) => String(value ?? '').replace(/([_*`\[])/g, '\\$1');
const money = (value) => `$${Number(value).toFixed(2)}`;
const signedPct = (value) => `${value > 0 ? '+' : ''}${Number(value).toFixed(2)}%`;

const describe = (row) => {
  const title = `[${escapeMarkdown(row.title)}](${row.url})`;
  if (row.change_type === 'NEW') {
    return `- ${title}: ${money(row.price)} (new listing)`;
  }
  return `- ${title}: ${money(row.previous_price)} -> *${money(row.price)}* (${signedPct(row.price_delta_pct)})`;
};

const section = (heading, rows) => {
  if (rows.length === 0) return [];
  const lines = rows.slice(0, MAX_LINES_PER_SECTION).map(describe);
  if (rows.length > MAX_LINES_PER_SECTION) {
    lines.push(`_...and ${rows.length - MAX_LINES_PER_SECTION} more_`);
  }
  return ['', `*${heading} (${rows.length})*`, ...lines];
};

const byMagnitude = (a, b) => Math.abs(b.price_delta_pct) - Math.abs(a.price_delta_pct);
const anomalies = changes.filter((r) => r.is_anomaly).sort(byMagnitude);
const priceDown = changes.filter((r) => r.change_type === 'PRICE_DOWN' && !r.is_anomaly).sort(byMagnitude);
const priceUp = changes.filter((r) => r.change_type === 'PRICE_UP' && !r.is_anomaly).sort(byMagnitude);
const newListings = changes.filter((r) => r.change_type === 'NEW');

const lines = [
  '*Laptop Price Monitor - Change Report*',
  `Run: \`${escapeMarkdown(snapshot.runId)}\` | ${escapeMarkdown(snapshot.scrapedAt)}`,
  `Scanned: ${snapshot.productCount} products across ${snapshot.pagesFetched} pages | Changes: ${changes.length}`,
  ...section('ANOMALY - price moved beyond threshold', anomalies),
  ...section('Price drops', priceDown),
  ...section('Price increases', priceUp),
  ...section('New listings', newListings),
];

if (snapshot.truncatedAtMaxPages) {
  lines.push('', '_Warning: pagination stopped at the maxPages safety bound; results may be incomplete._');
}

return [
  {
    json: {
      text: lines.join('\n').slice(0, 4000),
      changeCount: changes.length,
      anomalyCount: anomalies.length,
    },
  },
];

const input = $input.first().json;
const state = $('Pagination State').first().json;

let stage;
let detail;

if (input.error !== undefined) {
  stage = 'HTTP_TRANSPORT';
  detail = typeof input.error === 'string' ? input.error : input.error.message ?? JSON.stringify(input.error);
} else if (input.status === 'error') {
  stage = 'EXTRACTION';
  detail = input.reason;
} else {
  stage = 'HTTP_STATUS';
  detail = `Unexpected HTTP ${input.statusCode ?? 'n/a'} ${input.statusMessage ?? ''}`.trim();
}

const page = input.page ?? state.page ?? 'n/a';
const pagesFetched = input.pagesFetched ?? state.pagesFetched ?? 0;
const runId = input.runId ?? state.runId ?? String($execution.id);
const failedUrl = `https://webscraper.io/test-sites/e-commerce/static/computers/laptops?page=${page}`;

const escapeMarkdown = (value) => String(value ?? '').replace(/([_*`\[])/g, '\\$1');

const text = [
  '*Laptop Price Monitor - RUN ABORTED*',
  `Stage: \`${stage}\``,
  `Page: ${page} | Pages completed before failure: ${pagesFetched}`,
  `URL: ${failedUrl}`,
  `Detail: ${escapeMarkdown(detail)}`,
  `Run: \`${escapeMarkdown(runId)}\` | ${escapeMarkdown($now.toISO())}`,
  '_No snapshot was persisted for this run._',
].join('\n');

return [
  {
    json: {
      stage,
      detail,
      page,
      runId,
      failedUrl,
      text,
      summary: `Laptop price scrape aborted at stage ${stage} (page ${page}): ${detail}`,
    },
  },
];

const event = $input.first().json;
const execution = event.execution || {};
const lastNode = execution.lastNodeExecuted ?? event.trigger?.error?.node?.name ?? 'unknown';

// The controlled failure branch already alerted before "Abort Execution" raised the error.
if (lastNode === 'Abort Execution') {
  return [];
}

const escapeMarkdown = (value) => String(value ?? '').replace(/([_*`\[])/g, '\\$1');
const message = execution.error?.message ?? event.trigger?.error?.message ?? 'Unknown error';

const text = [
  '*Laptop Price Monitor - UNHANDLED FAILURE*',
  `Workflow: ${escapeMarkdown(event.workflow?.name ?? 'n/a')}`,
  `Failed node: \`${escapeMarkdown(lastNode)}\``,
  `Error: ${escapeMarkdown(message)}`,
  `Execution: ${execution.url ?? execution.id ?? 'n/a'}`,
  `Mode: ${escapeMarkdown(execution.mode ?? 'n/a')}`,
].join('\n');

return [{ json: { text, lastNode, message } }];
